package com.erudit.quiz;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.quiz.model.QuizModels.*;import com.erudit.quiz.repository.QuizRepository;import com.erudit.quiz.service.QuizService;import java.util.*;import org.junit.jupiter.api.Test;
class QuizServiceTest {@Test void coversAuthoringHintAndSubmit(){var repository=mock(QuizRepository.class);var service=new QuizService(repository);UUID quiz=UUID.randomUUID(),attempt=UUID.randomUUID(),user=UUID.randomUUID();var started=new Attempt(attempt,quiz,user,"STARTED",null,0);var hinted=new Attempt(attempt,quiz,user,"STARTED",null,1);when(repository.attempt(attempt)).thenReturn(started);when(repository.hint(started)).thenReturn(hinted);when(repository.question(quiz)).thenReturn(new Question(UUID.randomUUID(),quiz,"Q",List.of("A","B"),1,"Hint"));when(repository.finish(started,1)).thenReturn(new Attempt(attempt,quiz,user,"COMPLETED",1,0));assertThat(service.hint(attempt).remaining()).isOne();assertThat(service.submit(attempt,1).score()).isOne();assertThatThrownBy(()->service.create("Q","P",List.of("A"),1,"H")).isInstanceOf(IllegalArgumentException.class);}}
